#include <bits/stdc++.h>
using namespace std;

int n;
string names[12];
long long Q[12], V[12], M[12], L[12];
long long capM, capL;
long long bestVal;
long long bestSol[12], curSol[12];
int order[12];

double lpBound(int idx, long long rm, long long rl, long long curVal) {
    double ub = (double)curVal;
    long long trm = rm, trl = rl;
    for (int ii = idx; ii < n; ii++) {
        int i = order[ii];
        long long maxByM = (M[i] > 0) ? trm / M[i] : (long long)1e18;
        long long maxByL = (L[i] > 0) ? trl / L[i] : (long long)1e18;
        long long canTake = min({Q[i], maxByM, maxByL});
        if (canTake >= Q[i]) {
            ub += (double)V[i] * Q[i];
            trm -= M[i] * Q[i];
            trl -= L[i] * Q[i];
        } else {
            double fM = (M[i] > 0) ? (double)trm / M[i] : 1e18;
            double fL = (L[i] > 0) ? (double)trl / L[i] : 1e18;
            double frac = min({(double)Q[i], fM, fL});
            if (frac > 0) ub += (double)V[i] * frac;
            break;
        }
    }
    return ub;
}

void solve(int idx, long long rm, long long rl, long long curVal) {
    if (curVal > bestVal) {
        bestVal = curVal;
        memcpy(bestSol, curSol, sizeof(bestSol));
    }
    if (idx == n) return;
    if (lpBound(idx, rm, rl, curVal) <= (double)bestVal + 0.5) return;

    int i = order[idx];
    long long maxByM = (M[i] > 0) ? rm / M[i] : (long long)1e18;
    long long maxByL = (L[i] > 0) ? rl / L[i] : (long long)1e18;
    long long maxTake = min({Q[i], maxByM, maxByL});

    // Try from max down; if range is huge, sample key points
    if (maxTake <= 10000) {
        for (long long k = maxTake; k >= 0; k--) {
            curSol[i] = k;
            solve(idx + 1, rm - k * M[i], rl - k * L[i], curVal + k * V[i]);
        }
    } else {
        // Try max, max-1, ..., max-5, then 0..5, and boundary points
        vector<long long> cands;
        for (long long d = 0; d <= min(maxTake, 50LL); d++) cands.push_back(maxTake - d);
        for (long long d = 0; d <= min(maxTake, 50LL); d++) cands.push_back(d);
        sort(cands.rbegin(), cands.rend());
        cands.erase(unique(cands.begin(), cands.end()), cands.end());
        for (long long k : cands) {
            curSol[i] = k;
            solve(idx + 1, rm - k * M[i], rl - k * L[i], curVal + k * V[i]);
        }
    }
    curSol[i] = 0;
}

int main(){
    capM = 20000000LL; capL = 25000000LL;
    string input((istreambuf_iterator<char>(cin)),{});
    // Parse JSON: {"name": [q,v,m,l], ...}
    vector<pair<string,vector<long long>>> entries;
    size_t pos = 0;
    while((pos = input.find('"', pos)) != string::npos) {
        size_t end = input.find('"', pos+1); if(end==string::npos) break;
        string key = input.substr(pos+1, end-pos-1); pos = end+1;
        size_t br = input.find('[', pos); if(br==string::npos) break;
        size_t br2 = input.find(']', br); if(br2==string::npos) break;
        string arr = input.substr(br+1, br2-br-1); pos = br2+1;
        vector<long long> nums; stringstream ss(arr); string tok;
        while(getline(ss, tok, ',')) { long long v=0; bool neg=false; for(char c:tok){if(c=='-')neg=true;if(c>='0'&&c<='9')v=v*10+(c-'0');} if(neg)v=-v; nums.push_back(v); }
        if(nums.size()==4) entries.push_back({key, nums});
    }
    n = entries.size();
    for(int i=0;i<n;i++){names[i]=entries[i].first;Q[i]=entries[i].second[0];V[i]=entries[i].second[1];M[i]=entries[i].second[2];L[i]=entries[i].second[3];order[i]=i;}
    // Sort by value density (value per unit of most binding resource)
    sort(order, order+n, [](int a, int b){
        double wa = (double)V[a] / (1e-15 + max((double)M[a]/capM, (double)L[a]/capL));
        double wb = (double)V[b] / (1e-15 + max((double)M[b]/capM, (double)L[b]/capL));
        return wa > wb;
    });
    bestVal = -1; memset(bestSol, 0, sizeof(bestSol)); memset(curSol, 0, sizeof(curSol));
    solve(0, capM, capL, 0);
    cout << "{";
    for(int i=0;i<n;i++){if(i)cout<<", ";cout<<"\""<<names[i]<<"\": "<<bestSol[i];}
    cout << "}" << endl;
}
